declare_lint_rule! {
    /// Require lifecycle hooks to be placed before test cases in the same block.
    ///
    /// Lifecycle hooks such as `beforeAll`, `beforeEach`, `afterEach`, and
    /// `afterAll` describe the setup and teardown shared by the test cases in a
    /// block. Placing them after a test case makes it harder to spot the setup
    /// and teardown for these tests at a glance.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// describe('foo', () => {
    ///   it('should do bar', () => {});
    ///   beforeEach(() => {});
    /// });
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// it('should do foo', () => {});
    /// afterAll(() => {});
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// describe('foo', () => {
    ///   beforeEach(() => {});
    ///   it('should do bar', () => {});
    /// });
    /// ```
    ///
    pub UseTestHooksOnTop {
        version: "next",
        name: "useTestHooksOnTop",
        language: "js",
        recommended: false,
        severity: Severity::Warning,
        domains: &[RuleDomain::Test],
    }
}

declare_node_union! {
    /// A node that represents a scope containing test/describe calls:
    /// either the top-level module/script, or a `describe(...)` call.
    pub AnyTestScope = JsModule | JsScript | JsCallExpression
}

impl Rule for UseTestHooksOnTop {
    type Query = Ast<AnyTestScope>;
    type State = JsCallExpression;
    type Signals = Vec<Self::State>;
    type Options = UseTestHooksOnTopOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let scope = ctx.query();

        // For a JsCallExpression, only act when it is a describe block.
        if let AnyTestScope::JsCallExpression(call) = scope {
            if !is_describe_call(call) {
                return vec![];
            }
            let Some(stmts) = describe_body_statements(call) else {
                return vec![];
            };
            return check_direct_children(&stmts);
        }

        // For the top-level module or script, gather the top-level statements.
        let stmts: Vec<AnyJsStatement> = match scope {
            AnyTestScope::JsModule(module) => module
                .items()
                .into_iter()
                .filter_map(|item| {
                    if let AnyJsModuleItem::AnyJsStatement(stmt) = item {
                        Some(stmt)
                    } else {
                        None
                    }
                })
                .collect(),
            AnyTestScope::JsScript(script) => script.statements().into_iter().collect(),
            AnyTestScope::JsCallExpression(_) => unreachable!(),
        };
        check_direct_children(&stmts)
    }

    fn diagnostic(_: &RuleContext<Self>, node: &Self::State) -> Option<RuleDiagnostic> {
        let hook_name = callee_name(node)?;

        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Lifecycle hook "{hook_name.as_str()}" appears after a test case."
                },
            )
            .note(markup! {
                "Placing the hook after this test case makes it harder to spot the setup and teardown for these tests at a glance."
            })
            .note(markup! {
                "Move the hook above all test cases in the same block for better readability."
            }),
        )
    }
}

/// Lifecycle hook function names that must appear before any test case.
const HOOK_NAMES: &[&str] = &[
    "beforeAll",
    "beforeEach",
    "afterEach",
    "afterAll",
    "before",
    "after",
];

/// Test case function names that, once seen, cause any subsequent hook in the
/// same scope to be flagged.
const TEST_NAMES: &[&str] = &["it", "test"];

/// Checks a flat list of statements for lifecycle hooks placed after a test
/// case.
///
/// Only looks at the **direct children** of the current scope — does not
/// recurse. Recursion is handled by the query firing again for each nested
/// `describe` call.
///
/// Returns every hook call that appears after at least one test case at this
/// level. Each offending hook produces its own signal.
fn check_direct_children(statements: &[AnyJsStatement]) -> Vec<JsCallExpression> {
    let mut seen_test = false;
    let mut hooks_after_test = vec![];

    for stmt in statements {
        let Some(call) = call_from_statement(stmt) else {
            continue;
        };
        let Some(name) = callee_name(&call) else {
            continue;
        };

        if TEST_NAMES.contains(&name.as_str()) {
            seen_test = true;
        } else if seen_test && HOOK_NAMES.contains(&name.as_str()) {
            hooks_after_test.push(call);
        }
    }

    hooks_after_test
}

/// Returns the list of direct-child statements from the callback passed to a
/// `describe(...)` call, or `None` if the callback is not a recognisable
/// function literal with a block body.
fn describe_body_statements(call: &JsCallExpression) -> Option<Vec<AnyJsStatement>> {
    let args = call.arguments().ok()?;
    let [_, callback_arg] = args.get_arguments_by_index([0, 1]);
    let callback_arg = callback_arg?;
    let expr = callback_arg.as_any_js_expression()?;

    let body = match expr {
        AnyJsExpression::JsArrowFunctionExpression(arrow) => arrow.body().ok()?,
        AnyJsExpression::JsFunctionExpression(func) => {
            AnyJsFunctionBody::JsFunctionBody(func.body().ok()?)
        }
        _ => return None,
    };

    let AnyJsFunctionBody::JsFunctionBody(block) = body else {
        return None;
    };

    Some(block.statements().into_iter().collect())
}

/// Extracts the (single) `JsCallExpression` from an expression statement, if
/// the statement is of the form `call_expr(...)`.
fn call_from_statement(stmt: &AnyJsStatement) -> Option<JsCallExpression> {
    let expr_stmt = stmt.as_js_expression_statement()?;
    let expr = expr_stmt.expression().ok()?;
    expr.as_js_call_expression().cloned()
}

/// Returns the plain identifier name of the callee, e.g. `beforeEach` for
/// `beforeEach(() => {})`. Returns `None` for anything other than a bare
/// identifier callee.
fn callee_name(call: &JsCallExpression) -> Option<String> {
    let callee = call.callee().ok()?.omit_parentheses();
    let AnyJsExpression::JsIdentifierExpression(ident) = callee else {
        return None;
    };
    let token = ident.name().ok()?.value_token().ok()?;
    Some(token.text_trimmed().to_string())
}
